import functools


def 记一笔(fn):
    @functools.wraps(fn)
    def 包装(*args, **kwargs):
        print("要开演了")
        return fn(*args, **kwargs)

    return 包装


@记一笔
def 翻三倍(n):
    return n * 3


print(翻三倍({n}))
